import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadRailwaysData(){const e=readFileSync(resolve(__dirname,"../../frontend/mountain-railways-explorer/railways-data.js"),"utf-8");return new Function(e+"\nreturn { RAILWAYS_INFO, ENGINEERING_MARVELS, MOUNTAIN_RAILWAYS, GALLERY_IMAGES };")()}describe("UNESCO Mountain Railways of India Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadRailwaysData()}),describe("RAILWAYS_INFO metadata",()=>{it("contains correct UNESCO metadata and railway counts",()=>{expect(e.RAILWAYS_INFO.id).toBe("mountain-railways"),expect(e.RAILWAYS_INFO.totalRailways).toBe(3),expect(e.RAILWAYS_INFO.highestStation).toContain("Ghum")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.RAILWAYS_INFO.quickStats)).toBe(!0),expect(e.RAILWAYS_INFO.quickStats.length).toBe(6)})}),describe("ENGINEERING_MARVELS",()=>{it("contains overview, mechanisms, and status",()=>{expect(e.ENGINEERING_MARVELS.overview).toBeDefined(),expect(e.ENGINEERING_MARVELS.mechanisms).toBeDefined(),expect(e.ENGINEERING_MARVELS.conservationStatus).toBeDefined()})}),describe("MOUNTAIN_RAILWAYS catalog",()=>{it("covers Darjeeling Himalayan, Nilgiri Mountain, and Kalka-Shimla railways",()=>{expect(Array.isArray(e.MOUNTAIN_RAILWAYS)).toBe(!0),expect(e.MOUNTAIN_RAILWAYS.length).toBe(3);const t=e.MOUNTAIN_RAILWAYS.find(e=>"darjeeling-himalayan"===e.id),a=e.MOUNTAIN_RAILWAYS.find(e=>"nilgiri-mountain"===e.id),i=e.MOUNTAIN_RAILWAYS.find(e=>"kalka-shimla"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(i).toBeDefined(),expect(t.unescoYear).toBe(1999),expect(a.unescoYear).toBe(2005),expect(i.unescoYear).toBe(2008)})}),describe("GALLERY_IMAGES",()=>{it("is a non-empty array of gallery images",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBe(3)})})});